CREATE TABLE IF NOT EXISTS `hg_youban_publish_cms_app` (`id` bigint NOT NULL AUTO_INCREMENT,`app_id` varchar(128) NOT NULL,`app_secret` varchar(255) NOT NULL DEFAULT '',`name` varchar(128) NOT NULL DEFAULT '',`base_url` varchar(500) NOT NULL DEFAULT '',`instance_id` varchar(128) NOT NULL DEFAULT '',`enroll_hash` varchar(128) NOT NULL DEFAULT '',`source_ip` varchar(64) NOT NULL DEFAULT '',`cms_version` varchar(64) NOT NULL DEFAULT '',`last_heartbeat_at` datetime NULL,`review_mode` varchar(32) NOT NULL DEFAULT 'review_required',`status` tinyint NOT NULL DEFAULT 1,`created_at` datetime NULL,`updated_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ybp_cms_app_app_id` (`app_id`));
CREATE TABLE IF NOT EXISTS `hg_youban_publish_cms_binding_code` (`id` bigint NOT NULL AUTO_INCREMENT,`app_id` varchar(128) NOT NULL,`code_hash` varchar(128) NOT NULL,`code_hint` varchar(32) NOT NULL DEFAULT '',`version` int NOT NULL DEFAULT 1,`status` tinyint NOT NULL DEFAULT 1,`created_at` datetime NULL,`updated_at` datetime NULL,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `hg_youban_publish_cms_tenant_binding` (`id` bigint NOT NULL AUTO_INCREMENT,`app_id` varchar(128) NOT NULL,`tenant_id` bigint NOT NULL,`code_version` int NOT NULL DEFAULT 1,`status` varchar(32) NOT NULL DEFAULT 'approved',`reason` varchar(255) NOT NULL DEFAULT '',`requested_at` datetime NULL,`reviewed_at` datetime NULL,`created_at` datetime NULL,`updated_at` datetime NULL,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `hg_youban_open_profile_event` (`id` bigint NOT NULL AUTO_INCREMENT,`app_id` varchar(128) NOT NULL,`event_id` varchar(128) NOT NULL,`actor_id` varchar(128) NOT NULL,`profile_id` bigint NOT NULL,`event_type` varchar(32) NOT NULL,`occurred_at` datetime NULL,`created_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ybo_event_app_event` (`app_id`,`event_id`),KEY `idx_ybo_event_app_profile_time` (`app_id`,`profile_id`,`created_at`));
CREATE TABLE IF NOT EXISTS `hg_youban_open_profile_metric_daily` (`id` bigint NOT NULL AUTO_INCREMENT,`app_id` varchar(128) NOT NULL,`profile_id` bigint NOT NULL,`metric_date` date NOT NULL,`view_count` int NOT NULL DEFAULT 0,`unique_view_count` int NOT NULL DEFAULT 0,`favorite_count` int NOT NULL DEFAULT 0,`created_at` datetime NULL,`updated_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ybo_metric_app_profile_date` (`app_id`,`profile_id`,`metric_date`),KEY `idx_ybo_metric_app_date` (`app_id`,`metric_date`));
CREATE TABLE IF NOT EXISTS `hg_youban_open_profile_actor_daily` (`id` bigint NOT NULL AUTO_INCREMENT,`app_id` varchar(128) NOT NULL,`actor_id` varchar(128) NOT NULL,`profile_id` bigint NOT NULL,`metric_date` date NOT NULL,`created_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ybo_actor_daily` (`app_id`,`actor_id`,`profile_id`,`metric_date`));
CREATE TABLE IF NOT EXISTS `hg_youban_open_profile_signal` (`id` bigint NOT NULL AUTO_INCREMENT,`app_id` varchar(128) NOT NULL,`actor_id` varchar(128) NOT NULL,`profile_id` bigint NOT NULL,`view_count` int NOT NULL DEFAULT 0,`is_favorite` tinyint NOT NULL DEFAULT 0,`last_interaction_at` datetime NULL,`created_at` datetime NULL,`updated_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ybo_signal_app_actor_profile` (`app_id`,`actor_id`,`profile_id`),KEY `idx_ybo_signal_app_actor_time` (`app_id`,`actor_id`,`last_interaction_at`));
